import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("policy viewer", () => {
  test("policy viewer", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-01");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    await ui.setSetting(pg_uma, "floor", "2.00");
    expect(await ui.setSettingDated(pg_uma, "terms", "5", "2026-03-10", "14")).toBe(true);
    expect(await ui.setSettingDated(pg_uma, "rounding", "half-up", "2026-02-01", "half-up")).toBe(true);
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00", "date": "2026-02-20"}));
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00"}));
    const c_ada_2 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "30.00", "date": "2026-03-10"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_2, "open")).toBe(true);
    expect(await ui.policyLines(pg_uma)).toEqual(["1 2026-03-01 floor=2.00 1", "2 2026-03-10 terms=5 1", "3 2026-02-01 rounding=half-up 1"]);
    expect(await ui.setSettingDated(pg_uma, "late-pct", "10.00", "2026-03-10", "0.00")).toBe(true);
    expect(await ui.policyLines(pg_uma)).toEqual(["1 2026-03-01 floor=2.00 1", "2 2026-03-10 terms=5 1", "3 2026-02-01 rounding=half-up 0", "4 2026-03-10 late-pct=10.00 1"]);
