test("policy viewer scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  await ui.setSetting(pg_uma, "cap", "5.00");
  await ui.setSetting(pg_uma, "perm-void", "steward");
  await ui.setSetting(pg_uma, "note-threshold", "2.50");
  expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
  await ui.setSetting(pg_uma, "grace-C", "5");
  await ui.setSetting(pg_uma, "proof-threshold-A", "0.50");
  await ui.setSetting(pg_uma, "pot", "7.77");
  await ui.setSetting(pg_uma, "alert-threshold", "1.00");
  expect(await ui.setSettingDated(pg_uma, "rounding", "half-even", "2026-03-01", "half-even")).toBe(true);
  await ui.setSetting(pg_uma, "review-sla", "5");
  await ui.setSetting(pg_uma, "default-grade", "A");
  await ui.setSetting(pg_uma, "clerk-limit-A", "9.00");
  await ui.setSetting(pg_uma, "score-mid", "0");
  await ui.setSetting(pg_uma, "score-high", "1");
  expect(await ui.addGrade(pg_uma, "D")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "contact": " Ada@x "}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "terms": "20", "contact": "ben@x"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "70.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "20.00", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPool(pg_uma, "P2")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P2", {"member": "Ben", "share": "100.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "pool:P2", "share": "10.00"})).toBe(true);
  expect(await ui.editPerson(pg_uma, p_ben, {"terms": "3", "termsFrom": "2026-03-01"})).toBe(true);
  const pl_cam_1 = ui.must(await ui.addPlan(pg_uma, p_cam, {"amount": "1.00", "start": "2026-02-20", "end": "2026-04-30", "day": "31"}));
  expect(await ui.policyLines(pg_uma)).toEqual(["1 2026-04-05 clerk-limit=3.00 0", "2 2026-04-05 cap=5.00 0", "3 2026-03-01 rounding=half-even 0"]);
  expect(await ui.addAlias(pg_uma, p_ada, "Al")).toBe(true);
  expect(await ui.setSettingDated(pg_uma, "late-pct", "0.00", "2026-03-05", "0.00")).toBe(true);
  await ui.sortBy(pg_uma, "added");
test("policy viewer scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "terms", "7");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "terms-B", "20");
  await ui.setSetting(pg_uma, "proof-threshold", "1.00");
  await ui.setSetting(pg_uma, "grace-days", "3");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  await ui.setSetting(pg_uma, "proof-threshold-A", "0.50");
  expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
  await ui.setSetting(pg_uma, "pot", "33.33");
  await ui.setSetting(pg_uma, "alert-threshold", "3.00");
  await ui.setSetting(pg_uma, "review-threshold", "1.50");
  await ui.setSetting(pg_uma, "review-sla", "1");
  await ui.setSetting(pg_uma, "default-grade", "A");
  await ui.setSetting(pg_uma, "score-mid", "0");
  await ui.setSetting(pg_uma, "score-high", "5");
  await ui.setSetting(pg_uma, "score-log", "on");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00", "from": "2026-03-10"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C", "terms": "3"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "33.33"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "33.33"})).toBe(true);
  expect(await ui.addPool(pg_uma, "P2")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P2", {"member": "Cam", "share": "100.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "pool:P2", "share": "10.00"})).toBe(true);
  expect(await ui.addCrew(pg_uma, "C1", "Cam")).toBe(true);
  expect(await ui.editPerson(pg_uma, p_cam, {"terms": "20", "termsFrom": "2026-03-01"})).toBe(true);
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "1.00", "date": "2026-03-09", "tags": " c "}));
  expect(await ui.importPeople(pg_uma, "Cam,B\nFay,B,,")).toMatchObject({"added": 1, "updated": 1});
  const p_fay = await ui.personId(pg_uma, "Fay");
  const c_fay_0 = ui.must(await ui.addClaim(pg_uma, p_fay, {"amount": "7.77", "date": "2026-04-02", "note": "n"}));
  expect(await ui.statement(pg_uma, p_fay)).toBe(true);
  expect(await ui.pasteClaims(pg_uma, "Ada,20.00,2026-03-20,\nAda,0.40,2026-03-01,a, b\nZed,4.00,2026-04-02,a, b")).toBeNull();
  expect(await ui.ratePreview(pg_uma, "A", "20.00")).toEqual({ count: 0, diff: "0.00" });
  expect(await ui.claimAction(pg_uma, c_fay_0, "void", "late")).toBe(true);
