    /** The claim's timeline: the audit lines about it, newest first. */
    /** The sheet's duplicate claims, one line per person, date and amount claimed two or more times. */
    @GetMapping("/claims/duplicates")
    public List<String> duplicates(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return service.duplicates(sheetId);
    }

    @GetMapping("/claims/{id}/timeline")
    public List<String> timeline(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id) {
        return service.timeline(sheetId, id);
    private final Audit audit;

    public ClaimService(ClaimRepository claims, ClaimTagRepository tags, PersonRepository people, RateChain rates,
            PeriodRepository periods, SheetService sheets, RollupService rollup, SettingsService settings,
            WatchService watches, HolidayService holidays, VoidReasonService voidReasons, AsOfService asOf,
            Audit audit) {
        this.claims = claims;
        this.tags = tags;
        this.people = people;
        this.rates = rates;
        this.periods = periods;
        this.sheets = sheets;
        this.rollup = rollup;
        this.settings = settings;
        this.watches = watches;
        this.holidays = holidays;
        this.voidReasons = voidReasons;
        this.asOf = asOf;
        this.audit = audit;
    }

    /** All the claims on the sheet, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
    }

    /**
     * The sheet's duplicate claims: for each person, date and amount with two or more claims (VOID and DELETED ones
     * left out), one line {@code <name> <date> <amount> x<count>}; people in list order, then by date, then by amount.
     */
    @Transactional(readOnly = true)
    public List<String> duplicates(String sheetId) {
        record Key(LocalDate date, BigDecimal amount) {}
        Map<Long, Map<Key, Integer>> counts = new HashMap<>();
        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            if (c.getStatus() == ClaimStatus.VOID || c.getStatus() == ClaimStatus.DELETED) continue;
            counts.computeIfAbsent(c.getPersonId(), k -> new TreeMap<>(
                    Comparator.comparing(Key::date).thenComparing(Key::amount)))
                    .merge(new Key(c.getDate(), c.getAmount().setScale(2, RoundingMode.HALF_UP)), 1, Integer::sum);
        }
        List<String> lines = new ArrayList<>();
        for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            counts.getOrDefault(p.getId(), Map.of()).forEach((k, n) -> {
                if (n >= 2) lines.add(p.getName() + " " + k.date() + " " + k.amount().toPlainString() + " x" + n);
            });
        }
        return lines;
    }

    /**
     * The claim's timeline: the audit lines about it, newest first, as the file holds them (see
     * {@link Audit#claimLines}).
     */
    @Transactional(readOnly = true)
    public List<String> timeline(String sheetId, Long id) {
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
        Person person = person(sheetId, claim.getPersonId());
        return audit.claimLines(sheetId, claim.getNumber(), person.getName(), claim.getAmount().toPlainString(),
                claim.getDate().toString());
    }

